-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Maîtriser le CRM Entasis (maitriser-le-crm) ──
do $schemas_maitriser_le_crm$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$maitriser-le-crm$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$maitriser-le-crm$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$maitriser-le-crm$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"statuts","titre":"Le parcours d’un dossier et ses quatre statuts","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>Le parcours d’un dossier et ses quatre statuts</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<defs>\n<marker id=\"fleche\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n<path d=\"M 0 0 L 10 5 L 0 10 z\" fill=\"#C5A55A\"/>\n</marker>\n</defs>\n<text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Le parcours d’un dossier</text>\n<text x=\"320\" y=\"56\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Quatre statuts, et la date que chacun exige</text>\n<rect x=\"15\" y=\"86\" width=\"138\" height=\"96\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"84\" y=\"114\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">RDV calé</text>\n<text x=\"84\" y=\"134\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">valeur « Prévu »</text>\n<rect x=\"27\" y=\"144\" width=\"114\" height=\"26\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"84\" y=\"162\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Date prévue</text>\n<rect x=\"251\" y=\"86\" width=\"138\" height=\"96\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"114\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">En cours</text>\n<text x=\"320\" y=\"134\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">dossier ouvert</text>\n<rect x=\"263\" y=\"144\" width=\"114\" height=\"26\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"162\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Date prévue</text>\n<rect x=\"487\" y=\"86\" width=\"138\" height=\"96\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"556\" y=\"114\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">Signé</text>\n<text x=\"556\" y=\"134\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">dossier conclu</text>\n<rect x=\"499\" y=\"144\" width=\"114\" height=\"26\" rx=\"8\" fill=\"#C5A55A\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"556\" y=\"162\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#162443\">Date effective</text>\n<line x1=\"155\" y1=\"134\" x2=\"247\" y2=\"134\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/>\n<text x=\"202\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">RDV tenu</text>\n<line x1=\"391\" y1=\"134\" x2=\"483\" y2=\"134\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/>\n<text x=\"438\" y=\"124\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">trois verrous</text>\n<polyline points=\"84,184 84,290 245,290\" fill=\"none\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/>\n<text x=\"94\" y=\"228\" font-size=\"13\" fill=\"#2C3548\">No show</text>\n<line x1=\"320\" y1=\"184\" x2=\"320\" y2=\"246\" stroke=\"#C5A55A\" stroke-width=\"2\" marker-end=\"url(#fleche)\"/>\n<text x=\"330\" y=\"220\" font-size=\"13\" fill=\"#2C3548\">Abandonner</text>\n<rect x=\"251\" y=\"252\" width=\"138\" height=\"76\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"282\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#162443\">Annulé</text>\n<text x=\"320\" y=\"304\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">aucune date exigée</text>\n<rect x=\"415\" y=\"232\" width=\"210\" height=\"64\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"427\" y=\"260\" font-size=\"13\" font-weight=\"700\" fill=\"#162443\">Le lendemain d’un RDV calé :</text>\n<text x=\"427\" y=\"282\" font-size=\"13\" fill=\"#2C3548\">« RDV tenu » ou « No show »</text>\n<text x=\"320\" y=\"348\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Pour signer : fiche complète, produit choisi et date effective.</text>\n</svg>","legende":"Deux statuts vivants, deux issues. En cours et RDV calé exigent la date prévue, Signé la date effective, et Annulé s’atteint par le no show du lendemain ou par un abandon."},{"cle":"ma_journee","titre":"Ma journée et les dossiers sans mouvement","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>Ma journée et les dossiers sans mouvement</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<text x=\"320\" y=\"32\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Ma journée et les dossiers sans mouvement</text>\n<text x=\"320\" y=\"54\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Deux blocs de l’accueil, aucun geste en commun</text>\n<rect x=\"14\" y=\"70\" width=\"300\" height=\"270\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"164\" y=\"96\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#162443\">Ma journée</text>\n<text x=\"164\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">en haut de l’accueil « Mon mois »</text>\n<circle cx=\"40\" cy=\"142\" r=\"11\" fill=\"#162443\"/>\n<text x=\"40\" y=\"147\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#FFFFFF\">1</text>\n<text x=\"60\" y=\"147\" font-size=\"14\" fill=\"#2C3548\">Les RDV du jour</text>\n<circle cx=\"40\" cy=\"172\" r=\"11\" fill=\"#162443\"/>\n<text x=\"40\" y=\"177\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#FFFFFF\">2</text>\n<text x=\"60\" y=\"177\" font-size=\"14\" fill=\"#2C3548\">Les relances en retard</text>\n<circle cx=\"40\" cy=\"202\" r=\"11\" fill=\"#162443\"/>\n<text x=\"40\" y=\"207\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#FFFFFF\">3</text>\n<text x=\"60\" y=\"207\" font-size=\"14\" fill=\"#2C3548\">Les relances du jour</text>\n<rect x=\"30\" y=\"224\" width=\"268\" height=\"66\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"44\" y=\"244\" font-size=\"13\" font-weight=\"700\" fill=\"#162443\">Trois gestes</text>\n<rect x=\"44\" y=\"252\" width=\"66\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"77\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Fait</text>\n<rect x=\"118\" y=\"252\" width=\"86\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"161\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">→ demain</text>\n<rect x=\"212\" y=\"252\" width=\"72\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"248\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">→ +7 j</text>\n<text x=\"164\" y=\"312\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">annulables sept secondes</text>\n<text x=\"164\" y=\"332\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">« Fait » arme l’étape suivante</text>\n<rect x=\"326\" y=\"70\" width=\"300\" height=\"270\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"476\" y=\"96\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"#162443\">Dossiers sans mouvement</text>\n<text x=\"476\" y=\"116\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">plus bas, quand les trois sont réunies</text>\n<rect x=\"338\" y=\"133\" width=\"18\" height=\"18\" rx=\"4\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"362\" y=\"147\" font-size=\"14\" fill=\"#2C3548\">Statut En cours</text>\n<rect x=\"338\" y=\"163\" width=\"18\" height=\"18\" rx=\"4\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"362\" y=\"177\" font-size=\"14\" fill=\"#2C3548\">Aucune relance datée</text>\n<rect x=\"338\" y=\"193\" width=\"18\" height=\"18\" rx=\"4\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"362\" y=\"207\" font-size=\"14\" fill=\"#2C3548\">Plus de 21 jours sans modification</text>\n<rect x=\"342\" y=\"224\" width=\"268\" height=\"88\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"356\" y=\"244\" font-size=\"13\" font-weight=\"700\" fill=\"#162443\">Quatre gestes</text>\n<rect x=\"356\" y=\"252\" width=\"104\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"408\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Déjà signé</text>\n<rect x=\"470\" y=\"252\" width=\"126\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"533\" y=\"270\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Toujours en cours</text>\n<rect x=\"356\" y=\"284\" width=\"104\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"408\" y=\"302\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Relancer</text>\n<rect x=\"470\" y=\"284\" width=\"126\" height=\"26\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"533\" y=\"302\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Abandonner</text>\n<text x=\"476\" y=\"332\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">aucun geste de « Ma journée » ici</text>\n</svg>","legende":"Les deux blocs de l’accueil ne partagent aucun geste : trois dans « Ma journée », quatre dans « Dossiers sans mouvement », qui ne retient que les dossiers En cours sans relance datée."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 2 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"statuts"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 2 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 2, $academy_deck$choix$academy_deck$, $academy_deck$Créer un dossier$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Vous enregistrez le dossier de Monsieur Piel en statut En cours ; le CRM refuse. Produit et compagnie sont renseignés, la fiche est à « Signature 6/6 ». Quel champ manque le plus probablement ?","choix":["« Date de signature effective »","« Date de signature prévue »","« Co-conseiller »","« Source »"],"figure":{"ref":"statuts"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$La « Date de signature prévue » est obligatoire pour En cours et RDV calé ; la date effective ne l'est que pour Signé.$academy_deck$);
  end if;
  if v_max >= 6 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"ma_journee"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 6 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 6, $academy_deck$choix$academy_deck$, $academy_deck$Trier sans mouvement$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Le dossier de Madame Ferrand est En cours, sans relance datée, non modifié depuis 25 jours : il est dans « Dossiers sans mouvement ». Elle vous confirme que le dossier avance, mais aucune date n'est possible. Quel geste sur la ligne ?","choix":["« → +7 j »","« Toujours en cours »","« Abandonner »","« Déjà signé »"],"figure":{"ref":"ma_journee"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$« Toujours en cours » fait taire le dossier 21 jours de plus ; « → +7 j » appartient à « Ma journée ».$academy_deck$);
  end if;
  if v_max >= 10 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"ma_journee"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 10 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 10, $academy_deck$choix$academy_deck$, $academy_deck$Programmer le suivi$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Le dossier de Madame Vial est En cours, sa relance « Pour le » date d'il y a dix jours et personne n'a touché le dossier depuis 30 jours. Où le CRM le fait-il remonter ce matin ?","choix":["Dans « Dossiers sans mouvement », avec « 30 jours sans mouvement »","Dans « Ma journée », parmi les relances en retard","Dans « Signés, fiche à finir »","Nulle part : il faut le chercher dans le pipeline"],"figure":{"ref":"ma_journee"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$Une relance en retard est dans « Ma journée » ; « Dossiers sans mouvement » ne retient que les dossiers sans relance datée.$academy_deck$);
  end if;
  if v_max >= 27 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"statuts"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 27 and type = $academy_deck$association$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 27, $academy_deck$association$academy_deck$, $academy_deck$Créer un dossier$academy_deck$, 2, $academy_deck${"enonce":"Associez chaque statut de dossier à ce qui le caractérise.","gauche":["En cours","RDV calé","Signé","Annulé"],"droite":["Dossier ouvert, « Date de signature prévue » obligatoire","Colonne « Signé ✓ », « Date de signature effective » obligatoire","Issue de « Abandonner » ou de « No-show »","Valeur « Prévu », brouillon posé par la Lead Room"],"figure":{"ref":"statuts"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"paires":[[0,0],[1,3],[2,1],[3,2]]}$academy_deck$::jsonb, $academy_deck$Quatre statuts : En cours et RDV calé exigent la date prévue, Signé la date effective, Annulé vient d'un abandon ou d'un no-show.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"statuts"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$multi$academy_deck$, $academy_deck$Créer un dossier$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, cochez les statuts dont la case porte l’étiquette « Date prévue ».","choix":["RDV calé","En cours","Signé","Annulé"],"figure":{"ref":"statuts"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1]}$academy_deck$::jsonb, $academy_deck$RDV calé et En cours partagent la même obligation, la « Date de signature prévue » ; Signé demande la date effective et Annulé n’exige aucune date.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"statuts"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$choix$academy_deck$, $academy_deck$Trier sans mouvement$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, deux flèches entrent dans « Annulé ». Laquelle part du statut En cours ?","choix":["« Abandonner »","« No-show »","« RDV tenu »","« Déjà signé »"],"figure":{"ref":"statuts"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Un dossier En cours part en Annulé par « Abandonner » ; l’autre entrée vient de RDV calé, le lendemain, par le « No-show ». « RDV tenu » mène à En cours et « Déjà signé » ouvre la modale en Signé.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"ma_journee"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$trou_choix$academy_deck$, $academy_deck$Programmer le suivi$academy_deck$, 2, $academy_deck${"phrase":"Sur le schéma, un seul de ces gestes n’appartient ni à « Ma journée » ni à « Dossiers sans mouvement » : ___.","choix":["« Fait »","« Relancer »","« Toujours en cours »","« No-show »"],"figure":{"ref":"ma_journee"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":3}$academy_deck$::jsonb, $academy_deck$Les deux blocs de l’accueil proposent sept gestes en tout : trois dans « Ma journée », quatre dans « Dossiers sans mouvement ». « No-show » appartient à la carte du pipeline, le lendemain d’un RDV calé.$academy_deck$);
  end if;
end
$schemas_maitriser_le_crm$;
